//! Push delivery for incidents — a coalesced [`bsc_incident::Incident`] becomes a notification on
//! your phone.
//!
//! # ntfy first, and why
//!
//! [ntfy](https://ntfy.sh) is a tiny pub/sub push server you can SELF-HOST. A single authenticated
//! POST from this machine becomes a real OS notification on a phone whose app is closed — with no
//! Apple Developer account, no Firebase, and (self-hosted) nothing leaving your own network. That is
//! the fastest honest path to "a deauth attack buzzes my phone", and it fits the rest of this system:
//! local, private, no third party in the middle you did not choose.
//!
//! # The shape: pure mapping, thin transport
//!
//! Turning an incident into a message — its title, its priority, the emoji that make it glanceable,
//! the body that leads with the evidence an attacker cannot forge — is a PURE function
//! ([`ntfy_message`]), tested against a constructed incident with no network. The POST that actually
//! ships it lives behind [`PushTransport`], so the interesting decisions are all testable and the
//! wire is a thin implementation. Swapping ntfy for an APNs/FCM wake later changes the transport, not
//! the mapping.


pub use label_for::label_for;
pub use ntfy_message::ntfy_message;
pub use priority_for::priority_for;
pub use tags_for::tags_for;

use bsc_incident::Incident;
use serde::{Deserialize, Serialize};

/// One ntfy message — the wire shape of a push. Pure data; building it needs no network.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct NtfyMessage {
    /// The topic to publish to (the phone subscribes to this).
    pub topic: String,
    /// The notification title — short, glanceable.
    pub title: String,
    /// ntfy priority, 1 (min) .. 5 (max). 5 breaks through Do-Not-Disturb.
    pub priority: u8,
    /// Emoji shortcodes / keywords ntfy renders as icons.
    pub tags: Vec<String>,
    /// The notification body.
    pub body: String,
    /// Render the body as markdown on the phone.
    pub markdown: bool,
    /// A deep link the notification opens (e.g. into mobile-studio-code).
    pub click: Option<String>,
}

/// Where an ntfy server is and which topic to publish to. The auth token is NOT here — it is a
/// secret and belongs in the keychain, handed to the transport, never serialised beside the URL.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct NtfyConfig {
    /// e.g. `https://ntfy.example.lan`.
    pub base_url: String,
    /// e.g. `home-net-alerts`.
    pub topic: String,
}

/// The delivery boundary. Behind this trait the mapping is testable with a recording fake and the
/// real wire is a thin implementation — so a test never hits the network and a transport swap
/// (ntfy → an APNs/FCM wake) never touches the mapping.
pub trait PushTransport {
    /// Publish `msg` to the server at `base_url`. `base_url` has no trailing slash.
    fn send(&self, base_url: &str, msg: &NtfyMessage) -> Result<(), String>;
}

/// The real ntfy transport: an authenticated blocking POST. `POST {base_url}/{topic}` with the
/// title/priority/tags as headers and the body as the payload, per ntfy's publish API.
pub struct HttpNtfy {
    /// A bearer token from the keychain, or `None` for an open server.
    pub token: Option<String>,
    /// How long to wait before giving up — a push must never wedge the caller.
    pub timeout: std::time::Duration,
}

impl Default for HttpNtfy {
    fn default() -> Self {
        HttpNtfy { token: None, timeout: std::time::Duration::from_secs(10) }
    }
}

impl PushTransport for HttpNtfy {
    fn send(&self, base_url: &str, msg: &NtfyMessage) -> Result<(), String> {
        let url = format!("{}/{}", base_url.trim_end_matches('/'), msg.topic);
        let client = reqwest::blocking::Client::builder()
            .timeout(self.timeout)
            .build()
            .map_err(|e| format!("http client: {e}"))?;
        let mut req = client
            .post(&url)
            .header("Title", &msg.title)
            .header("Priority", msg.priority.to_string())
            .header("Tags", msg.tags.join(","))
            .body(msg.body.clone());
        if msg.markdown {
            req = req.header("Markdown", "yes");
        }
        if let Some(click) = &msg.click {
            req = req.header("Click", click);
        }
        if let Some(token) = &self.token {
            req = req.header("Authorization", format!("Bearer {token}"));
        }
        let resp = req.send().map_err(|e| format!("ntfy POST to {url}: {e}"))?;
        if resp.status().is_success() {
            Ok(())
        } else {
            Err(format!("ntfy returned {} for {url}", resp.status()))
        }
    }
}

/// Deliver an incident as a push: map it, then hand it to the transport. The one call a caller makes.
pub fn push_incident(
    transport: &dyn PushTransport,
    cfg: &NtfyConfig,
    inc: &Incident,
) -> Result<(), String> {
    transport.send(&cfg.base_url, &ntfy_message(inc, &cfg.topic))
}
